<?php require_once __DIR__.'/../../includes/functions.php';$u=require_auth();$d=request_json();verify_csrf($d['_csrf']??'');$f=owned_file((int)($d['id']??0),$u['id']);$star=empty($d['star'])?0:1;db()->prepare('UPDATE files SET is_starred=? WHERE id=? AND user_id=?')->execute([$star,$f['id'],$u['id']]);log_activity($u['id'],$star?'Star':'Unstar',$f['id'],$f['folder_id'],($star?'Starred ':'Unstarred ').$f['file_name']);json_response(['ok'=>1,'starred'=>$star]);